const errorLog = global.get('parat_bridge.error_log') || [];

const recent = errorLog.slice(0, 10);

msg.payload = recent.map(e => ({
    time: e.timestamp.replace('T', ' ').substring(0, 19),
    type: e.type ? e.type.toUpperCase() : 'UNKNOWN',
    source: e.source,
    status: e.statusCode || 'none',
    severity: e.severity || 'warning',
    message: (e.raw_message || e.message || '').substring(0, 60)
}));

return msg;

const connections = global.get("parat_bridge.connections");

if (!connections) {
    msg.payload = [];
    return msg;
}


msg.payload = Object.values(connections).map(conn => {
    const clients = Object.values(conn.clients);
    return {
        "Klient 1": `${clients[0].client_system} — ${clients[0].name}`,
        "Klient 2": `${clients[1].client_system} — ${clients[1].name}`,
        status:     conn.active ? "🟢 aktiv" : "🔴 inaktiv",
        created:    new Date(conn.time_created).toLocaleString()
    };
});


return msg;

// Initialize context — sets runtime config only
// Connections and queue are already in cache (loaded by context store on open)
const pb = global.get("parat_bridge") || {};

pb.base_urls = {
    rayvn: "https://api.rayvn.global",
    wasos: "https://dev.wasos.no"
};

if (!pb.queue) pb.queue = { in_flight_connections: [], entry_queue: [] };
pb.queue.in_flight_connections = [];  // always reset on startup

global.set("parat_bridge", pb);

const conns = Object.keys(global.get("parat_bridge.connections") || {}).length;
const queue = (global.get("parat_bridge.queue.entry_queue") || []).length;
node.log("Active: " + conns + " connection(s), " + queue + " queued entries");

return msg;

global.set('utils', {

    build_connection_name: (clients) => {
        return [...clients]
            .sort((a, b) => a.client_system.localeCompare(b.client_system))
            .map(c => `${c.client_system}-${c.identifier}`)
            .join("_");
    },

    build_label: (client) => {
        const colors = {
            wasos:        "#1f871f",
            rayvn:        "#000000",
            parat_bridge: "#b80d18"
        };
        return {
            id:       client.identifier,
            name:     `[${client.client_system}]: ${client.name}`,
            colorHex: colors[client.client_system] || "#888888"
        };
    },

    build_callsign: (client) => `[${client.client_system}:${client.name}]`,

    FILE_REASONS: {
        OVERSIZED:        "oversized",
        NON_TRANSFERABLE: "non_transferable",
        DOWNLOAD_FAILED:  "download_failed",
        UPLOAD_FAILED:    "upload_failed"
    },

    build_file_key: (message_id, connection_name, filename) => {
        const safe = filename.replace(/[\\\/\:*?"<>|]/g, "_");
        return message_id + "---" + connection_name + "---" + safe;
    },

    parse_file_key: (key) => {
        const raw   = key.startsWith("files.") ? key.slice("files.".length) : key;
        const parts = raw.split("---");
        return {
            message_id:      parts[0]              || null,
            connection_name: parts[1]              || null,
            filename:        parts.slice(2).join("---") || null
        };
    }

});

return msg;

const log = global.get('parat_bridge.error_log') || [];
log.unshift(msg.error_context);
if (log.length > 100) log.length = 100;
global.set('parat_bridge.error_log', log);

return msg;

const ctx = msg.error_context || {};
const code = ctx.statusCode;

let type, severity, userMessage;

if (!code) {
    type = 'network';
    severity = 'critical';
    userMessage = '⚠️ Forbindelsen er midlertidig nede. Meldinger vil ikke leveres før forbindelsen er gjenopprettet.';
} else if (code === 401 || code === 403) {
    type = 'auth';
    severity = 'critical';
    userMessage = '⚠️ Autentisering feilet. Kontakt administrator for å fornye tilgangen.';
} else if (code >= 500) {
    type = 'server';
    severity = 'critical';
    userMessage = '⚠️ Ekstern tjeneste svarer ikke. Meldinger vil ikke leveres før tjenesten er tilgjengelig igjen.';
} else if (code === 404) {
    type = 'not_found'; severity = 'warning'; userMessage = null;
} else if (code === 429) {
    type = 'rate_limit'; severity = 'warning'; userMessage = null;
} else if (code >= 400) {
    type = 'client'; severity = 'warning'; userMessage = null;
} else {
    type = 'unknown'; severity = 'warning'; userMessage = null;
}

msg.error_context = Object.assign({}, ctx, {
    type,
    severity,
    message: type === 'network' ? 'Nettverksfeil' : `HTTP ${code}`,
    notify_users: !!(userMessage && ctx.connection_name),
    user_message: userMessage
});

return msg;

const ctx = msg.error_context || {};

if (!ctx.notify_users || !ctx.connection_name) return null;

// Cascade-vern: dropp hvis entry_id starter med pb-err-
if (ctx.entry_id && ctx.entry_id.startsWith('pb-err-')) return null;

// Notification throttle: maks 1 notifikasjon per connection per 5 min
const cb = global.get('parat_bridge.circuit_breaker') || {};
const cbEntry = cb[ctx.connection_name] || {};
const now = Date.now();

if (cbEntry.last_notified && (now - cbEntry.last_notified) < 5 * 60 * 1000) return null;

cb[ctx.connection_name] = { last_notified: now };
global.set('parat_bridge.circuit_breaker', cb);

const connections = global.get('parat_bridge.connections') || {};
const conn = connections[ctx.connection_name];
if (!conn) return null;

const messages = Object.values(conn.clients).map(client => ({
    topic: 'new_message',
    entry: {
        id: 'pb-err-' + now + '-' + Math.random().toString(36).slice(2, 7),
        text: ctx.user_message,
        author: '[parat_bridge]',
        metadata: {
            source: { client_system: 'parat_bridge', connection_name: ctx.connection_name },
            target: client,
            connection_name: ctx.connection_name
        }
    }
}));

return messages.map(m => ({ payload: m }));

var connections = global.get('parat_bridge.connections') || {};
msg = {
    topic: 'connections/update',
    payload: connections
};
return msg;

/**
 * Build a user-facing notification about file transfer failures.
 * Groups failed files by reason and builds one combined message.
 */
const utils = global.get("utils");
const event = msg.payload;

const groups = {};
for (const f of (event.failed_files || [])) {
    if (!groups[f.reason]) groups[f.reason] = [];
    groups[f.reason].push(f.name);
}

const lines = [];

if (groups[utils.FILE_REASONS.OVERSIZED]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.OVERSIZED].length
        + " vedlegg for store for mottakersystemet (maks 1 MB): "
        + groups[utils.FILE_REASONS.OVERSIZED].join(", ") + ".");
}

if (groups[utils.FILE_REASONS.NON_TRANSFERABLE]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.NON_TRANSFERABLE].length
        + " vedlegg kan ikke overføres automatisk. "
        + "Tips: Høyreklikk på vedlegg → «Kopier adresse» → lim inn adressen som tekst.");
}

if (groups[utils.FILE_REASONS.DOWNLOAD_FAILED]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.DOWNLOAD_FAILED].length
        + " vedlegg kunne ikke lastes ned fra kildesystemet: "
        + groups[utils.FILE_REASONS.DOWNLOAD_FAILED].join(", ") + ".");
}

if (groups[utils.FILE_REASONS.UPLOAD_FAILED]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.UPLOAD_FAILED].length
        + " vedlegg ble avvist av mottakersystemet: "
        + groups[utils.FILE_REASONS.UPLOAD_FAILED].join(", ") + ".");
}

if (lines.length === 0) return null;

msg._notification_text = lines.join(" ");
msg._event = event;

return msg;

/**
 * Wrap the notification text in a bridge entry format
 * that can be sent through the queue to the sender's system.
 *
 * The entry is addressed FROM parat_bridge TO the sender.
 * This means it goes to the same system the sender used,
 * so they see the notification in their own interface.
 *
 * client_system is set to 'parat_bridge' so the Filter subflow
 * recognises and drops it when polled back, preventing loops.
 *
 * Returns a clean object — no inherited properties.
 */
const event    = msg._event;
const metadata = event.metadata;
const now      = Date.now();

return {
    topic: "new_message",
    entry: {
        id:        "pb-att-" + now + "-" + Math.random().toString(36).substr(2, 6),
        text:      msg._notification_text,
        timestamp: now,
        author:    "System-melding",
        labels:    [],
        metadata: {
            source: {
                client_system: "parat_bridge",
                name:          "parat_bridge",
                identifier:    "parat_bridge"
            },
            target:          metadata.source,
            connection_name: metadata.connection_name,
            files: null
        }
    }
};

// Frigjør in-flight slot
const connection_name = (msg.metadata && msg.metadata.connection_name)
    || (msg.entry && msg.entry.metadata && msg.entry.metadata.connection_name)
    || null;

if (connection_name) {
    const queue = global.get('parat_bridge.queue') || {};
    const inFlight = (queue.in_flight_connections || []).filter(n => n !== connection_name);
    global.set('parat_bridge.queue.in_flight_connections', inFlight);

    // Inkrementer retries for entry i køen
    const entryQueue = queue.entry_queue || [];
    const entry_id = msg.entry && msg.entry.id;
    if (entry_id) {
        const idx = entryQueue.findIndex(e => e.entry.id === entry_id);
        if (idx !== -1) {
            entryQueue[idx]._retries = (entryQueue[idx]._retries || 0) + 1;
            if (entryQueue[idx]._retries >= 10) {
                // Dropp alle entries for denne connection
                const filtered = entryQueue.filter(e =>
                    !(e.entry.metadata && e.entry.metadata.connection_name === connection_name)
                );
                global.set('parat_bridge.queue.entry_queue', filtered);
            } else {
                global.set('parat_bridge.queue.entry_queue', entryQueue);
            }
        }
    }
}

msg.error_context = {
    timestamp: new Date().toISOString(),
    source: msg.error && msg.error.source ? msg.error.source.name : 'unknown',
    raw_message: msg.error ? msg.error.message : null,
    statusCode: (msg.payload && msg.payload.statusCode) || null,
    connection_name: connection_name,
    entry_id: (msg.entry && msg.entry.id) || null,
    direction: 'unknown'
};

return msg;

const entry    = msg.entry || {};
const metadata = entry.metadata || {};
const target   = metadata.target || {};

const sourceMap = {
    rayvn: 'POST to Rayvn log',
    wasos: 'POST to WaSOS chat',
    cim:   'POST to CIM'
};

msg.error_context = {
    timestamp:       new Date().toISOString(),
    source:          sourceMap[target.client_system] || 'POST entries',
    raw_message:     null,
    statusCode:      (msg.payload && msg.payload.statusCode) || null,
    connection_name: metadata.connection_name || null,
    entry_id:        entry.id || null,
    direction:       'outbound'
};

return msg;
